278	func (h *AdminHandlers) UnbanIP(w http.ResponseWriter, r *http.Request) {
279		// 从查询参数中获取IP，这样更合理且避免了URL path中的特殊字符问题
280		ip := r.URL.Query().Get("ip")
281		if ip == "" {
282			// 为了保持向后兼容性，尝试从路径参数中获取（如果使用了兼容层）
283			if vars, ok := r.Context().Value("muxVars").(map[string]string); ok {
284				ip = vars["ip"]
285			}
286			// 如果仍然没有IP，则返回错误
287			if ip == "" {
288				http.Error(w, "IP参数不能为空，请使用查询参数: ?ip=xxx.xxx.xxx.xxx", http.StatusBadRequest)
289				return
290			}
291		}
292	
293		log.Printf("开始解除IP封禁: %s", ip)
294	
295		// 使用模式匹配删除所有与该IP相关的缓存键
296		ctx := r.Context()
297		// 删除基本的封禁记录
298		if err := utils.UnbanIPInRedis(h.RedisClient, ctx, ip); err != nil {
299			log.Printf("从Redis解除IP封禁失败 %s: %v", ip, err)
300		} else {
301			log.Printf("成功从Redis解除IP封禁: %s", ip)
302		}
303	
304		// 使用多个模式匹配所有与IP相关的缓存键，包括限流计数器
305		patterns := []string{
306			fmt.Sprintf("*:%s:*", ip),                // 匹配包含IP作为中间部分的键
307			fmt.Sprintf("ratelimit:*:%s", ip),        // 匹配API和页面路由的限流计数器
308			fmt.Sprintf("ratelimit:static:%s:*", ip), // 匹配静态文件的限流计数器
309		}
310		var totalDeleted int64
311	
312		// 遍历所有模式，删除匹配的键
313		for _, pattern := range patterns {
314			var cursor uint64
315			for {
316				var keys []string
317				var err error
318				keys, cursor, err = h.RedisClient.Scan(ctx, cursor, pattern, 100).Result()
319				if err != nil {
320					log.Printf("Redis扫描键失败 %s: %v", pattern, err)
321					break
322				}
323	
324				if len(keys) > 0 {
325					affected, err := h.RedisClient.Del(ctx, keys...).Result()
326					if err != nil {
327						log.Printf("Redis删除键失败 %v: %v", keys, err)
328					} else {
329						totalDeleted += affected
330						log.Printf("删除了 %d 个与IP相关的缓存键: %v", affected, keys)
331					}
332				}
333	
334				if cursor == 0 {
335					break
336				}
337			}
338		}
339	
340		log.Printf("总共删除了 %d 个与IP %s 相关的缓存键", totalDeleted, ip)
341	
342		// 从数据库中移除封禁记录
343		// 直接使用SQL语句确保删除操作执行
344		result := h.DB.Exec("DELETE FROM banned_ips WHERE ip = ?", ip)
345		if result.Error != nil {
346			log.Printf("数据库解除封禁失败 %s: %v", ip, result.Error)
347			http.Error(w, "解除封禁失败: "+result.Error.Error(), http.StatusInternalServerError)
348			return
349		}
350	
351		log.Printf("数据库删除结果 - 影响行数: %d", result.RowsAffected)
352	
353		// 即使没有影响到行数，也返回成功，避免因为数据库和缓存不一致导致的问题
354		// 因为我们已经成功从Redis中移除了封禁
