  "old_string": "// GetRequestHeaders 将请求头转换为JSON字符串",
  "new_string": "// BanIPWithProgression 统一封禁入口，支持递增封禁
// baseDurationMinutes: 基准封禁时长（路径规则自带的或全局的）
// cfg: 全局配置，用于读取progressive_ban参数
// 返回实际封禁时长（分钟）
func BanIPWithProgression(db *gorm.DB, redisClient *redis.Client, ctx context.Context, ip string, reason string, baseDurationMinutes int, cfg interface{ GetProgressiveBan() (bool, int, int, int) }) int {
	enabled, windowMinutes, multiplier, maxMinutes := cfg.GetProgressiveBan()

	if !enabled {
		BanIP(db, ip, reason, baseDurationMinutes)
		BanIPInRedis(redisClient, ctx, ip, time.Duration(baseDurationMinutes)*time.Minute)
		return baseDurationMinutes
	}

	// 如果IP已有生效封禁，什么都不做
	if IsIPBanned(db, ip) {
		return 0
	}

	// 用数据库行锁保证并发安全：同一IP同一波攻击只记一次
	tx := db.Begin()
	if tx.Error != nil {
		BanIP(db, ip, reason, baseDurationMinutes)
		BanIPInRedis(redisClient, ctx, ip, time.Duration(baseDurationMinutes)*time.Minute)
		return baseDurationMinutes
	}

	var profile models.IPOffenseProfile
	// SELECT ... FOR UPDATE 锁定该行，防止并发写入
	err := tx.Raw("SELECT * FROM ip_offense_profiles WHERE ip = ? FOR UPDATE", ip).Scan(&profile).Error

	windowStart := time.Now().Add(-time.Duration(windowMinutes) * time.Minute)
	offensesInWindow := 0

	if err != nil || profile.IP == "" {
		// 不存在档案，创建新的
		offensesInWindow = 0
	} else {
		if profile.LastOffenseAt.After(windowStart) {
			offensesInWindow = profile.OffenseCount
		} else {
			offensesInWindow = 0
		}
	}

	// 计算递增时长
	duration := baseDurationMinutes
	for i := 0; i < offensesInWindow; i++ {
		duration *= multiplier
		if duration >= maxMinutes {
			duration = maxMinutes
			break
		}
	}

	newCount := offensesInWindow + 1
	now := time.Now()

	if profile.IP == "" {
		// INSERT
		if execErr := tx.Exec(
			"INSERT INTO ip_offense_profiles (ip, offense_count, last_offense_at) VALUES (?, ?, ?)",
			ip, newCount, now,
		).Error; execErr != nil {
			tx.Rollback()
			BanIP(db, ip, reason, duration)
			BanIPInRedis(redisClient, ctx, ip, time.Duration(duration)*time.Minute)
			return duration
		}
	} else {
		// UPDATE
		if execErr := tx.Exec(
			"UPDATE ip_offense_profiles SET offense_count = ?, last_offense_at = ? WHERE ip = ?",
			newCount, now, ip,
		).Error; execErr != nil {
			tx.Rollback()
			BanIP(db, ip, reason, duration)
			BanIPInRedis(redisClient, ctx, ip, time.Duration(duration)*time.Minute)
			return duration
		}
	}

	// 双写封禁记录
	bannedAt := now
	expiresAt := bannedAt.Add(time.Duration(duration) * time.Minute)

	var existingBan models.BannedIP
	result := tx.Where("ip = ?", ip).First(&existingBan)
	if result.Error == nil {
		existingBan.Reason = reason
		existingBan.BannedAt = bannedAt
		existingBan.ExpiresAt = expiresAt
		tx.Save(&existingBan)
	} else {
		tx.Create(&models.BannedIP{
			IP:        ip,
			Reason:    reason,
			BannedAt:  bannedAt,
			ExpiresAt: expiresAt,
		})
	}

	if commitErr := tx.Commit().Error; commitErr != nil {
		BanIP(db, ip, reason, duration)
	}

	BanIPInRedis(redisClient, ctx, ip, time.Duration(duration)*time.Minute)

	LogBan("IP已封禁(递增) - IP: %s, 时长: %d分钟, 窗口内违规次数: %d", ip, duration, newCount)
	return duration
}

